/**
 * On-screen rendering of the four invoice templates. Mirrors the server-side PDF layouts
 * closely so the preview is trustworthy, and works fully offline. The downloadable PDF is
 * always generated by the server.
 */
import { useEffect, useRef, useState, type CSSProperties } from "react";
import type { DocKind, ItemInput, PricingMode, Snapshot, TemplateKey } from "@/types";
import { cn } from "@/utils/cn";
import { computeDocument, dec, taxSummary } from "@/utils/calc";
import { amount, fmtDate, money, quantity, rate } from "@/utils/format";

export interface PreviewModel {
  kind: DocKind;
  number: string;
  issue_date: string;
  end_date: string;
  currency: string;
  pricing_mode: PricingMode;
  template: TemplateKey;
  accent: string;
  show_signature: boolean;
  business: Snapshot & { logo?: string | null };
  customer: Snapshot | null;
  items: ItemInput[];
  shipping: string;
  amount_paid?: string;
  notes: string | null;
  terms: string | null;
  payment_instructions: string | null;
  status?: string;
}

const PAGE_W = 794; // A4 at 96dpi

function lines(b: Snapshot) {
  const out: string[] = [];
  if (b.address) out.push(b.address);
  const contact = [b.phone, b.email].filter(Boolean).join(" · ");
  if (contact) out.push(contact);
  if (b.website) out.push(b.website);
  const ids = [b.kra_pin && `KRA PIN: ${b.kra_pin}`, b.vat_registered && b.vat_number && `VAT No: ${b.vat_number}`, b.registration_number && `Reg. No: ${b.registration_number}`].filter(Boolean);
  if (ids.length) out.push(ids.join(" · "));
  return out;
}

export function DocumentPreview({ model, className }: { model: PreviewModel; className?: string }) {
  const outer = useRef<HTMLDivElement>(null);
  const inner = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [height, setHeight] = useState(1123);

  useEffect(() => {
    if (!outer.current) return;
    const ro = new ResizeObserver(() => {
      const w = outer.current?.clientWidth ?? PAGE_W;
      setScale(Math.min(1, w / PAGE_W));
      setHeight(inner.current?.scrollHeight ?? 1123);
    });
    ro.observe(outer.current);
    if (inner.current) ro.observe(inner.current);
    return () => ro.disconnect();
  }, []);

  const m = model;
  const { lines: calc, totals } = computeDocument(m.items, m.shipping, m.pricing_mode);
  const taxes = taxSummary(m.items, calc);
  const paid = dec(m.amount_paid ?? "0");
  const balance = totals.total.minus(paid);
  const t = m.template;
  const accent = m.accent || "#0F766E";
  const title = m.kind === "invoice" ? "Invoice" : "Quotation";
  const endLabel = m.kind === "invoice" ? "Due date" : "Valid until";
  const hasDiscount = calc.some((l) => l.discount.gt(0));
  const hasTax = m.items.some((i) => dec(i.tax_rate).gt(0));
  const serif = t === "elegant";
  const font: CSSProperties = {
    fontFamily: t === "modern" ? "Poppins, Inter, system-ui, sans-serif" : serif ? "'Liberation Serif', 'Times New Roman', Georgia, serif" : "'Liberation Sans', Arial, Helvetica, sans-serif",
  };
  const stamp = m.status === "paid" ? "PAID" : m.status === "cancelled" ? "CANCELLED" : m.status === "draft" ? "DRAFT" : null;

  const Logo = ({ h = 56, center = false }: { h?: number; center?: boolean }) =>
    m.business.logo ? <img src={m.business.logo} alt="" style={{ maxHeight: h, maxWidth: 170 }} className={cn("object-contain", center && "mx-auto")} /> : null;

  const header = (() => {
    if (t === "corporate")
      return (
        <div className="flex justify-between gap-6 rounded-md p-7 text-white" style={{ background: accent }}>
          <div className="min-w-0">
            {m.business.logo && <div className="mb-3 inline-block rounded bg-white p-1.5"><Logo h={48} /></div>}
            <p className="text-[19px] font-bold">{m.business.name}</p>
            {lines(m.business).map((l) => <p key={l} className="whitespace-pre-line text-[11px] opacity-80">{l}</p>)}
          </div>
          <div className="text-right">
            <p className="text-[30px] font-bold tracking-wide">{title.toUpperCase()}</p>
            <p className="text-[13px] opacity-80">{m.number}</p>
          </div>
        </div>
      );
    if (t === "elegant")
      return (
        <div className="text-center">
          <Logo h={60} center />
          <p className="mt-2 text-[24px] font-bold">{m.business.name}</p>
          {lines(m.business).map((l) => <p key={l} className="whitespace-pre-line text-[11px] text-zinc-500">{l}</p>)}
          <div className="mt-4 border-t-[1.5px] pt-[2px]" style={{ borderColor: accent }}><div className="border-t" style={{ borderColor: accent }} /></div>
          <p className="mt-5 text-[22px] tracking-[0.35em]" style={{ color: accent }}>{title.toUpperCase()}</p>
          <p className="text-[12px] text-zinc-500">{m.number}</p>
        </div>
      );
    if (t === "classic")
      return (
        <div className="flex justify-between gap-6">
          <div className="min-w-0">
            <Logo h={56} />
            <p className="mt-1 text-[18px] font-bold">{m.business.name}</p>
            {lines(m.business).map((l) => <p key={l} className="whitespace-pre-line text-[11px] text-zinc-500">{l}</p>)}
          </div>
          <div className="w-[260px] shrink-0">
            <p className="mb-2 text-[26px] font-bold">{title.toUpperCase()}</p>
            <table className="w-full border border-zinc-900 text-[11px]">
              <tbody>
                {[[`${title} no.`, m.number], ["Issue date", fmtDate(m.issue_date)], [endLabel, fmtDate(m.end_date)]].map(([k, v]) => (
                  <tr key={k} className="border-b border-zinc-400 last:border-0">
                    <td className="border-r border-zinc-400 bg-zinc-100 px-2 py-1 font-bold">{k}</td>
                    <td className="px-2 py-1 text-right">{v}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
    return (
      <>
        <div className="flex justify-between gap-6">
          <div className="min-w-0">
            <Logo h={64} />
            <p className="mt-2 text-[18px] font-medium">{m.business.name}</p>
            {lines(m.business).map((l) => <p key={l} className="whitespace-pre-line text-[11px] text-zinc-500">{l}</p>)}
          </div>
          <div className="text-right">
            <p className="text-[38px] font-light leading-none">{title}</p>
            <p className="mt-1 text-[13px] text-zinc-500">{m.number}</p>
          </div>
        </div>
        <div className="mt-6 h-[2px]" style={{ background: accent }} />
      </>
    );
  })();

  const c = m.customer;
  const billTo = (
    <div>
      <p className="mb-1.5 text-[9.5px] font-bold uppercase tracking-wider text-zinc-500">{m.kind === "invoice" ? "Bill to" : "Prepared for"}</p>
      {c?.name ? (
        <>
          <p className="font-bold">{c.name}</p>
          {c.company && <p>{c.company}</p>}
          {c.billing_address && <p className="whitespace-pre-line">{c.billing_address}</p>}
          {(c.phone || c.email) && <p className="text-[11px] text-zinc-500">{[c.phone, c.email].filter(Boolean).join(" · ")}</p>}
          {c.tax_id && <p className="text-[11px] text-zinc-500">PIN / Tax ID: {c.tax_id}</p>}
        </>
      ) : (
        <p className="text-zinc-400">No customer selected</p>
      )}
    </div>
  );
  const dueLabel = m.kind === "invoice" ? "Amount due" : "Quotation total";
  const dueValue = m.kind === "invoice" ? balance : totals.total;

  const parties =
    t === "classic" ? (
      <div className="mt-7 flex justify-between gap-6">
        <div className="w-[55%] border border-zinc-900 p-3">{billTo}</div>
        <div className="text-right">
          <p className="text-[9.5px] font-bold uppercase tracking-wider">{dueLabel}</p>
          <p className="text-[21px] font-bold">{money(dueValue.toFixed(2), m.currency)}</p>
        </div>
      </div>
    ) : (
      <div className="mt-8 grid grid-cols-[1.15fr_1fr_0.9fr] gap-4">
        {billTo}
        <div>
          <p className="mb-1.5 text-[9.5px] font-bold uppercase tracking-wider text-zinc-500">Details</p>
          <table className="text-[11.5px]">
            <tbody>
              {[[`${title} no.`, m.number], ["Issue date", fmtDate(m.issue_date)], [endLabel, fmtDate(m.end_date)], ["Currency", m.currency], ...(m.pricing_mode === "inclusive" ? [["Prices", "Tax inclusive"]] : [])].map(([k, v]) => (
                <tr key={k}>
                  <td className="py-[1px] pr-3 text-zinc-500">{k}</td>
                  <td className={cn("py-[1px]", !serif && "font-bold")}>{v}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="text-right" style={t === "corporate" ? { background: `${accent}14`, padding: 10, borderRadius: 4 } : undefined}>
          <p className="mb-1.5 text-[9.5px] font-bold uppercase tracking-wider text-zinc-500">{dueLabel}</p>
          <p className="text-[22px] font-bold" style={{ color: serif ? undefined : accent }}>{money(dueValue.toFixed(2), m.currency)}</p>
          <p className="text-[11px] text-zinc-500">{m.kind === "invoice" ? "Due" : "Valid until"} {fmtDate(m.end_date)}</p>
        </div>
      </div>
    );

  const th = cn("px-1.5 py-2 text-[9.5px] font-bold uppercase tracking-wide", t === "corporate" ? "text-white" : "text-zinc-500", serif && "normal-case tracking-normal");
  const table = (
    <table className={cn("mt-8 w-full border-collapse text-[11.5px]", t === "classic" && "border border-zinc-900")}>
      <thead>
        <tr
          style={t === "corporate" ? { background: accent } : undefined}
          className={cn(t === "modern" && "border-b border-zinc-900", t === "elegant" && "border-y", t === "classic" && "bg-zinc-200 [&>th]:border [&>th]:border-zinc-500")}
        >
          <th className={cn(th, "w-7 text-left")}>#</th>
          <th className={cn(th, "text-left")}>Description</th>
          <th className={cn(th, "w-14 text-right")}>Qty</th>
          <th className={cn(th, "w-24 text-right")}>Unit price</th>
          {hasDiscount && <th className={cn(th, "w-16 text-right")}>Discount</th>}
          {hasTax && <th className={cn(th, "w-14 text-right")}>{m.pricing_mode === "exclusive" ? "Tax" : "Tax incl."}</th>}
          <th className={cn(th, "w-28 text-right")}>Amount ({m.currency})</th>
        </tr>
      </thead>
      <tbody>
        {m.items.length === 0 && (
          <tr><td colSpan={7} className="px-1.5 py-6 text-center text-zinc-400">No items yet</td></tr>
        )}
        {m.items.map((it, i) => {
          const l = calc[i];
          return (
            <tr
              key={i}
              className={cn("align-top", t === "classic" ? "[&>td]:border [&>td]:border-zinc-500" : "border-b border-zinc-200")}
              style={t === "corporate" && i % 2 === 1 ? { background: `${accent}0d` } : undefined}
            >
              <td className="px-1.5 py-2 text-zinc-400">{i + 1}</td>
              <td className="whitespace-pre-line break-words px-1.5 py-2">{it.description || <span className="text-zinc-400">Item description</span>}</td>
              <td className="px-1.5 py-2 text-right">{quantity(it.quantity || "0")}</td>
              <td className="px-1.5 py-2 text-right">{amount(it.unit_price || "0")}</td>
              {hasDiscount && <td className="px-1.5 py-2 text-right">{l.discount.gt(0) ? (it.discount_type === "percent" ? rate(it.discount_value) : amount(l.discount)) : "—"}</td>}
              {hasTax && <td className="px-1.5 py-2 text-right">{dec(it.tax_rate).gt(0) ? rate(it.tax_rate) : "—"}</td>}
              <td className={cn("px-1.5 py-2 text-right", !serif && "font-bold")}>{amount(l.total)}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );

  const row = (label: string, value: string, opts: { grand?: boolean; muted?: boolean } = {}) => (
    <div key={label} className={cn("flex justify-between gap-4 px-2 py-1", opts.grand && "mt-1 border-t border-zinc-900 py-2 text-[14px] font-bold", opts.muted && "text-[11px] text-zinc-500")}>
      <span>{label}</span>
      <span>{value}</span>
    </div>
  );
  const totalsBox = (
    <div className="w-[300px] shrink-0 text-[12px]">
      {row("Subtotal", money(totals.subtotal, m.currency))}
      {totals.discount_total.gt(0) && row("Discount", money(totals.discount_total.neg(), m.currency))}
      {m.pricing_mode === "exclusive" && taxes.map((x) => row(`${x.name} (${rate(x.rate)})`, money(x.amount, m.currency)))}
      {totals.shipping.gt(0) && row("Shipping & charges", money(totals.shipping, m.currency))}
      {row("Total", money(totals.total, m.currency), { grand: true })}
      {m.pricing_mode === "inclusive" && taxes.map((x) => row(`Includes ${x.name} (${rate(x.rate)})`, money(x.amount, m.currency), { muted: true }))}
      {m.kind === "invoice" && (
        <>
          {paid.gt(0) && row("Amount paid", money(paid.neg(), m.currency))}
          <div
            className={cn("mt-1 flex justify-between px-2 py-2 text-[14px] font-bold", t === "classic" && "border border-zinc-900 bg-zinc-100")}
            style={t === "modern" || t === "corporate" ? { background: accent, color: "#fff" } : t === "elegant" ? { background: `${accent}1a` } : undefined}
          >
            <span>Balance due</span>
            <span>{money(balance, m.currency)}</span>
          </div>
        </>
      )}
    </div>
  );

  const section = (label: string) => (
    <p className="mb-1 text-[10px] font-bold uppercase tracking-wider" style={{ color: t === "classic" ? undefined : accent }}>{label}</p>
  );

  return (
    <div ref={outer} className={cn("w-full overflow-hidden", className)} style={{ height: height * scale }}>
      <div
        ref={inner}
        className="relative origin-top-left bg-white px-[68px] py-[60px] text-zinc-900 shadow-pop ring-1 ring-zinc-200"
        style={{ width: PAGE_W, minHeight: 1123, transform: `scale(${scale})`, ...font }}
        aria-label={`${title} preview`}
      >
        {stamp && (
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center overflow-hidden" aria-hidden>
            <span className="rotate-[-32deg] text-[110px] font-bold" style={{ color: stamp === "PAID" ? "#059669" : stamp === "DRAFT" ? "#9ca3af" : "#dc2626", opacity: 0.09 }}>{stamp}</span>
          </div>
        )}
        {header}
        {parties}
        {table}
        <div className="mt-6 flex justify-between gap-8">
          <div className="min-w-0 flex-1 text-[11.5px]">
            {m.payment_instructions && (
              <>
                {section("Payment instructions")}
                <p className="whitespace-pre-line">{m.payment_instructions}</p>
                {m.kind === "invoice" && <p className="mt-2 text-[11px] text-zinc-500">Please quote <b>{m.number}</b> as your payment reference.</p>}
              </>
            )}
          </div>
          {totalsBox}
        </div>
        {m.notes && (
          <div className="mt-8 text-[11.5px]">
            {section("Notes")}
            <p className="whitespace-pre-line">{m.notes}</p>
          </div>
        )}
        {m.terms && (
          <div className="mt-6 text-[11px] text-zinc-500">
            {section("Terms & conditions")}
            <p className="whitespace-pre-line">{m.terms}</p>
          </div>
        )}
        {m.show_signature && (
          <div className="mt-14 flex justify-between text-[11px] text-zinc-500">
            <div className="w-[260px] border-t border-zinc-900 pt-1">{m.kind === "quotation" ? "Accepted by (name & signature)" : `Authorised signature — ${m.business.name ?? ""}`}</div>
            <div className="w-[170px] border-t border-zinc-900 pt-1">Date</div>
          </div>
        )}
      </div>
    </div>
  );
}
